bool CWorldMap::IsLineOfSight(const C3DVector& from, const C3DVector& to) const
{
    bool visible = true;
    C3DVector pos = from;
    float dx = to.X - from.X;
    float dy = to.Y - from.Y;
    float dz = to.Z - from.Z;
    float steps;
    C3DVector step;
    C3DVector& st = step;
    if (fabsf(dx) > fabsf(dy)) {
        steps = fabsf(dx);
        step.X = 1.0f;
        float inv = 1.0f / steps;
        step.Y = dy * inv;
        st.Z = dz * inv;
        if (dx < 0.0f)
            step.X = -1.0f;
    } else {
        steps = fabsf(dy);
        float inv = 1.0f / steps;
        step.Y = 1.0f;
        step.X = dx * inv;
        st.Z = dz * inv;
        if (dy < 0.0f)
            step.Y = -1.0f;
    }
    while (steps >= 1.0f) {
        unsigned char blocked = 0;
        for (long i = 0; i < 4; ++i) {
            C2DCoordI cell((long)((float)s_BlockCornerOffsets[i].x + pos.X), (long)((float)s_BlockCornerOffsets[i].y + pos.Y));
            if (GetThemeMinCameraSizeZOffsetAt(cell) > pos.Z)
                ++blocked;
            if (blocked == 4) {
                visible = false;
                break;
            }
        }
        if (!visible)
            break;
        pos.X += step.X;
        pos.Y += step.Y;
        pos.Z = step.Z + pos.Z;
        steps -= 1.0f;
    }
    return visible;
}

